def resize_billede_til_visning(billede_data):
    image_bytes = base64.b64decode(billede_data)
    billede = Image.open(BytesIO(image_bytes))
    bredde, hoejde = billede.size
    billede = billede.resize((bredde // 2, hoejde // 2))

    buffer = BytesIO()
    billede.save(buffer, format="JPEG")
    return base64.b64encode(buffer.getvalue()).decode("utf-8")


@app.route("/")
def velkommen():
    return render_template_string(VELKOMST_HTML, image_data=resize_billede_til_visning(Zombie1_DATA))


@app.route("/logreg", methods=["GET", "POST"])
def logreg():
    resultat = None
    if request.method == "POST":
        input_data = pd.DataFrame([{
            "battery_pct": float(request.form["battery_pct"]),
            "sensor_confidence_pct": float(request.form["sensor_confidence_pct"]),
            "task_risk_level": float(request.form["task_risk_level"]),
            "safety_check_passed": float(request.form["safety_check_passed"]),
        }])

        forudsigelse = MODEL.predict(input_data)[0]
        if forudsigelse == 1:
            return redirect(url_for("godkendt"))
        resultat = "Robot requires human supervision"

    return render_template_string(LOGREG_HTML, accuracy=round(ACCURACY * 100, 1), resultat=resultat)


