@app.route("/naeste-trin", methods=["GET", "POST"])
def naeste_trin():
    resultat = None
    if request.method == "POST":
        input_data = pd.DataFrame([{
            "fitness_score": float(request.form["fitness_score"]),
            "gaming_hours_week": float(request.form["gaming_hours_week"]),
            "run_speed_kmh": float(request.form["run_speed_kmh"]),
            "food_cans": float(request.form["food_cans"]),
            "distance_to_zombie_m": float(request.form["distance_to_zombie_m"]),
        }])

        forudsigelse = ZOMBIE_MODEL.predict(input_data)[0]
        overlevede = forudsigelse == 1
        if overlevede:
            resultat = "You survive the zombie apocalypse!"
        else:
            resultat = "You do not survive the zombie apocalypse."

    return render_template_string(
        ZOMBIE_MODEL_HTML,
        image_data=resize_billede_til_visning(Zombie3_DATA),
        accuracy=round(ZOMBIE_ACCURACY * 100, 1),
        resultat=resultat,
        overlevede=overlevede if request.method == "POST" else None,
    )


@app.route("/spil-videre")
def spil_videre():
    overlevede = request.args.get("resultat") == "overlevede"

    if overlevede:
        resultat = "You survive the zombie apocalypse!"
        status = "All good"
    else:
        resultat = "You do not survive the zombie apocalypse."
        status = "Too bad"

    return render_template_string(
        SPIL_SLUT_HTML,
        image_data=resize_billede_til_visning(Zombie4_DATA),
        resultat=resultat,
        status=status,
    )


@app.route("/stop", methods=["POST"])
def stop():
    def sluk_server():
        time.sleep(1)
        os._exit(0)

    threading.Thread(target=sluk_server).start()
    return render_template_string(STOP_HTML)


def main():
    app.run(debug=True)


